fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Requires: The `start` index must be within bounds such that the subarray can fit in the main array.
    // Ensures: Returns true if the subarray matches the main array starting at index `start`, false otherwise.
    // Invariant: 0 <= start <= main.len() and start + sub.len() <= main.len()
    // Decreases: main.len() - start

    assert!(start <= main.len()); // Ensure start is within bounds
    assert!(sub.len() <= main.len() - start); // Ensure subarray can fit

    if start + sub.len() > main.len() {
        return false;
    }
    
    // Check if the elements match
    for j in 0..sub.len() {
        // Invariant: 0 <= j < sub.len()
        assert!(j < sub.len()); // Ensure j is within bounds
        if main[start + j] != sub[j] {
            return false;
        }
    }
    
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Requires: The main array and subarray must be valid references.
    // Ensures: Returns true if the subarray is found within the main array, false otherwise.
    // Invariant: The subarray is empty or the main array is not empty.
    // Decreases: main.len() - sub.len()

    assert!(main.len() >= 0); // Ensure main array is valid
    assert!(sub.len() >= 0); // Ensure sub array is valid

    // An empty subarray is always a valid subarray
    if sub.is_empty() {
        return true;
    }
    
    // Check each possible starting index in the main array
    for k in 0..=main.len().saturating_sub(sub.len()) {
        // Invariant: 0 <= k <= main.len() - sub.len()
        assert!(k <= main.len() - sub.len()); // Ensure k is within bounds
        if check_match_at(main, sub, k) {
            return true;
        }
    }
    
    false
}

